
<style>*{box-sizing:border-box}.container{max-width:1200px;margin:30px auto;padding:0 16px}.tool-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:20px;align-items:start}.tool-main,.tool-sidebar{background:#fff;border:1px solid #e5e9f0;border-radius:20px;padding:25px;box-shadow:0 14px 40px rgba(20,30,70,.05)}.tool-sidebar{position:sticky;top:88px;max-height:calc(100vh - 108px);overflow:auto}.tool-sidebar a{display:block;padding:9px 10px;margin:3px 0;border-radius:9px;text-decoration:none;color:#536075;font-size:13px;font-weight:700}.tool-sidebar a:hover,.tool-sidebar a.active{background:#f0efff;color:#635bff}.input{width:100%;padding:12px;border:1px solid #dfe4ec;border-radius:10px;font:inherit;margin:8px 0 14px}.btn{border:0;border-radius:10px;padding:12px 18px;background:#635bff;color:#fff;font-weight:800;cursor:pointer;margin:4px 5px 10px 0}.result{margin-top:15px;padding:15px;background:#f7f8fb;border:1px solid #e5e9f0;border-radius:12px;min-height:55px;word-break:break-all;font-family:ui-monospace,monospace}@media(max-width:800px){.tool-layout{grid-template-columns:1fr}.tool-sidebar{position:static;max-height:330px}}</style><main class="container"><div class="tool-layout"><section class="tool-main"><h1>Text to Slug</h1><p>Convert titles and text into clean, SEO-friendly URL slugs.</p><textarea id="input" class="input" rows="7" placeholder="Enter your title or text..."></textarea><button class="btn" onclick="makeSlug()">Generate Slug</button><button class="btn" onclick="copySlug()">Copy Slug</button><button class="btn" onclick="clearText()">Clear</button><div class="result" id="result">Your slug will appear here.</div></section><aside class="tool-sidebar"><h2>🛠️ All Tools</h2><?php $items=['image-compressor.php'=>'🖼️ Image Compressor','png-to-jpg.php'=>'↩️ PNG to JPG','jpg-to-webp.php'=>'🖼️ JPG to WebP','png-to-webp.php'=>'🖼️ PNG to WebP','gif-maker.php'=>'🎞️ GIF Maker','pdf-to-jpg.php'=>'📄 PDF to JPG','pdf-to-png.php'=>'📄 PDF to PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','text-to-pdf.php'=>'📝 Text to PDF','qr-generator.php'=>'🔐 QR Code Generator','qr-reader.php'=>'📷 QR Code Reader','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','sort-lines.php'=>'↕️ Sort Lines','remove-extra-spaces.php'=>'🧹 Remove Extra Spaces','reverse-text.php'=>'↔️ Reverse Text','text-to-slug.php'=>'🔗 Text to Slug','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><script>let slug='';function makeSlug(){const text=document.getElementById('input').value.trim();slug=text.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s-]/g,'').replace(/[\s_-]+/g,'-').replace(/^-+|-+$/g,'');document.getElementById('result').textContent=slug||'No text entered.'}async function copySlug(){if(!slug)makeSlug();if(slug)await navigator.clipboard.writeText(slug)}function clearText(){document.getElementById('input').value='';slug='';document.getElementById('result').textContent='Your slug will appear here.'}</script>
